test('błąd składni nie pozostawia wcześniejszego rysunku', () => {
  const result = run('np 10\\nnieznane', '2d');
  expect(result.segments).toEqual([]);
  expect(result.error.line).toBe(2);
});
test('błąd wykonania zachowuje wcześniejszy rysunek', () => {
  const result = run('np 10\\nniech x 0\\nnp 1 / x', '2d');
  expect(result.segments.length).toBe(1);
  expect(result.error.line).toBe(3);
});
test('powtórzenie i obrót tworzą kwadrat', () => {
  const result = run('powtorz 4 [np 10 pw 90]', '2d');
  expect(result.error).toBeNull();
  expect(result.segments).toHaveLength(4);
  expect(result.segments[3].to[0]).toBeCloseTo(0);
  expect(result.segments[3].to[1]).toBeCloseTo(0);
});
test('obrót w przestrzeni kieruje żółwia w górę', () => {
  const result = run('gora 90 np 10', '3d');
  expect(result.segments[0].to[2]).toBeCloseTo(10);
});
