cat >> tests/interpreter.test.js <<'EOF'
test('procedura może zostać wywołana przed definicją', () => {
 const result = run('kwadrat 10\\noto kwadrat ma: bok\\n powtorz 4 [np bok pw 90]\\njuż', '2d');
 expect(result.error).toBeNull();
 expect(result.segments).toHaveLength(4);
});
test('dzielenie przez zero w grubości jest błędem wykonania', () => {
 const result = run('np 10 grubosc 1 / 0', '2d');
 expect(result.segments).toHaveLength(1);
 expect(result.error).not.toBeNull();
});
test('polecenia przestrzenne w 2D są błędem przed rysowaniem', () => {
 const result = run('np 10 gora 90', '2d');
 expect(result.segments).toEqual([]);
 expect(result.error).not.toBeNull();
});
test('czyść usuwa wcześniejsze odcinki', () => {
 const result = run('np 10 czyść np 5', '2d');
 expect(result.segments).toEqual([{from:[0,10,0],to:[0,15,0],color:'#16866a',width:3}]);
});
EOF
